CREATE TABLE "public"."service_charge_flow_exceptions" ("flow_id" uuid NOT NULL, "created_at" timestamp NOT NULL DEFAULT now(), PRIMARY KEY ("flow_id") , FOREIGN KEY ("flow_id") REFERENCES "public"."flows"("id") ON UPDATE cascade ON DELETE cascade, UNIQUE ("flow_id"));COMMENT ON TABLE "public"."service_charge_flow_exceptions" IS E'IDs of flows within teams that otherwise have contracts which automatically apply service charges. Rows are added manually and should be approved by OSL staff';
